package daemon

import (
	"context"
	"errors"
	"os"
	"testing"
	"time"
)

func TestReadyTimeout_EnvOverride(t *testing.T) {
	for v, want := range map[string]time.Duration{
		"": ensureReadyBudget, "15s": 15 * time.Second, "junk": ensureReadyBudget, "-1s": ensureReadyBudget,
	} {
		t.Setenv(readyTimeoutEnv, v)
		if got := ReadyTimeout(); got != want {
			t.Errorf("%s=%q: ReadyTimeout() = %v, want %v", readyTimeoutEnv, v, got, want)
		}
	}
}

// A launcher that finds a fresh lease but no socket waits for the owner and
// spawns nothing: the spawn binary here would fail the test if it ran.
func TestEnsureDaemon_HeldLeaseDoesNotSpawn(t *testing.T) {
	root := t.TempDir()
	writeRecordForTest(t, root, nil)
	ctx, cancel := context.WithTimeout(context.Background(), 150*time.Millisecond)
	defer cancel()
	_, err := EnsureDaemon(ctx, root, "/nonexistent/wipnote", os.Getpid())
	if !errors.Is(err, ErrDaemonStarting) {
		t.Fatalf("err = %v, want ErrDaemonStarting (waiting on the owner, no spawn)", err)
	}
}
EOF
cat >> /workspaces/wipnote-lease/core/daemon/socket_guard_test.go <<'EOF'

// A launcher beside a live legacy owner leaves it alone: no spawn, and an
// error the launcher turns into its one-line notice.
func TestEnsureDaemon_LegacyOwnerNotDisturbed(t *testing.T) {
	bash, err := exec.LookPath("bash")
	if err != nil || !hasProcCmdline() {
		t.Skip("needs bash and /proc")
	}
	legacy := exec.Command(bash, "-c", "exec -a _serve-child sleep 30")
	if err := legacy.Start(); err != nil {
		t.Fatal(err)
	}
	defer func() { _ = legacy.Process.Kill(); _ = legacy.Wait() }()
	root := t.TempDir()
	_ = os.MkdirAll(filepath.Join(root, ".wipnote"), 0o755)
	_ = os.WriteFile(LegacyLeasePath(root), []byte(strconv.Itoa(legacy.Process.Pid)), 0o644)
	waitLegacyArgv(t, legacy.Process.Pid)
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	if _, err := EnsureDaemon(ctx, root, "/nonexistent/wipnote", os.Getpid()); !errors.Is(err, ErrDaemonLegacyOwner) {
		t.Fatalf("err = %v, want ErrDaemonLegacyOwner", err)
	}
}
EOF
